"use client";

import { useState, useEffect } from "react";
import { createClient } from "@/lib/supabase";
import { useParams, useRouter } from "next/navigation";
import styles from "../forum.module.css"; // Reuse existing styles

type Comment = {
    id: string;
    content: string;
    created_at: string;
    user_id: string;
};

type Post = {
    id: string;
    title: string;
    content: string;
    category: string;
    created_at: string;
    user_id: string;
};

export default function PostDetailPage() {
    const { id } = useParams();
    const router = useRouter();
    const supabase = createClient();

    const [post, setPost] = useState<Post | null>(null);
    const [comments, setComments] = useState<Comment[]>([]);
    const [loading, setLoading] = useState(true);
    const [newComment, setNewComment] = useState("");

    useEffect(() => {
        if (id) {
            fetchPostData();
        }
    }, [id]);

    const fetchPostData = async () => {
        setLoading(true);

        // 1. Fetch Post
        const { data: postData, error: postError } = await supabase
            .from('posts')
            .select('*')
            .eq('id', id)
            .single();

        if (postError) {
            console.error("Error fetching post:", postError);
            alert("Post not found");
            router.push('/dashboard/forum');
            return;
        }
        setPost(postData as any);

        // 2. Fetch Comments
        const { data: commentsData } = await supabase
            .from('comments')
            .select('*')
            .eq('post_id', id)
            .order('created_at', { ascending: true });

        if (commentsData) {
            setComments(commentsData as any);
        }

        setLoading(false);
    };

    const handlePostComment = async () => {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user || !newComment.trim()) return;

        const { error } = await supabase
            .from('comments')
            .insert({
                post_id: id,
                user_id: user.id,
                content: newComment
            });

        if (error) {
            alert("Error posting comment");
        } else {
            setNewComment("");
            fetchPostData(); // Refresh comments
        }
    };

    if (loading) return <div className={styles.container}><p style={{ padding: '2rem' }}>Loading discussion...</p></div>;
    if (!post) return null;

    return (
        <div className={styles.container} style={{ flexDirection: 'column', maxWidth: '800px', margin: '0 auto', height: 'auto' }}>

            {/* Back Button */}
            <button
                onClick={() => router.back()}
                style={{ background: 'none', border: 'none', color: 'var(--secondary-foreground)', cursor: 'pointer', alignSelf: 'flex-start', marginBottom: '-1rem' }}
            >
                ← Back to Forum
            </button>

            {/* Main Post */}
            <div className={styles.postCard} style={{ cursor: 'default' }}>
                <div className={styles.postHeader}>
                    <span className={styles.postCategory}>{post.category}</span>
                    <span style={{ fontSize: '0.8rem', color: 'var(--secondary-foreground)' }}>
                        {new Date(post.created_at).toLocaleDateString()}
                    </span>
                </div>
                <h1 style={{ fontSize: '1.75rem', fontWeight: 700, margin: '1rem 0' }}>{post.title}</h1>
                <p style={{ lineHeight: '1.6', fontSize: '1.05rem', whiteSpace: 'pre-wrap' }}>
                    {post.content}
                </p>
            </div>

            {/* Comments Section */}
            <div style={{ marginTop: '2rem' }}>
                <h3 style={{ marginBottom: '1rem' }}>Comments ({comments.length})</h3>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', marginBottom: '2rem' }}>
                    {comments.length === 0 ? (
                        <p style={{ color: 'var(--secondary-foreground)', fontStyle: 'italic' }}>No comments yet. Be the first to reply!</p>
                    ) : (
                        comments.map(comment => (
                            <div key={comment.id} style={{
                                padding: '1rem',
                                backgroundColor: 'var(--background)',
                                border: '1px solid var(--border)',
                                borderRadius: '0.75rem'
                            }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                    <span style={{ fontWeight: 600, fontSize: '0.9rem' }}>Student</span>
                                    <span style={{ fontSize: '0.75rem', color: 'var(--secondary-foreground)' }}>
                                        {new Date(comment.created_at).toLocaleString()}
                                    </span>
                                </div>
                                <p>{comment.content}</p>
                            </div>
                        ))
                    )}
                </div>

                {/* Comment Input */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                    <textarea
                        className={styles.textarea}
                        style={{ minHeight: '100px' }}
                        placeholder="Write a helpful reply..."
                        value={newComment}
                        onChange={e => setNewComment(e.target.value)}
                    />
                    <button
                        className={styles.newPostBtn}
                        style={{ width: 'fit-content', alignSelf: 'flex-end', padding: '0.75rem 2rem' }}
                        onClick={handlePostComment}
                        disabled={!newComment.trim()}
                    >
                        Post Reply
                    </button>
                </div>
            </div>
        </div>
    );
}
